SELECT
FROM customer_leads cl LEFT JOIN users u ON cl.salesperson_id = u.id WHERE 1=1
AND cl.salesperson_id = #{salespersonId}
AND cl.status = #{status}
AND cl.audit_status = #{auditStatus}
AND ( cl.name LIKE CONCAT('%', #{keyword}, '%') OR cl.phone LIKE CONCAT('%', #{keyword}, '%') OR cl.wechat_id LIKE CONCAT('%', #{keyword}, '%') OR cl.source LIKE CONCAT('%', #{keyword}, '%') OR cl.source_detail LIKE CONCAT('%', #{keyword}, '%') )
AND cl.source = #{source}
AND cl.created_at >= #{startDate}
AND cl.created_at <= #{endDate}
ORDER BY
cl.created_at
cl.updated_at
cl.name
cl.status
cl.audit_status
cl.last_follow_up_at
cl.source
cl.created_at
ASC
DESC
LIMIT #{offset}, #{limit}

